'use client'

import { useActionState } from 'react'

async function submitContactMessage(
  prevState: { message: string; success: boolean },
  formData: FormData
) {
  'use server'

  const name = formData.get('name')
  const email = formData.get('email')
  const message = formData.get('message')

  if (!name || !email || !message) {
    return { message: 'All fields are required', success: false }
  }

  if (typeof name !== 'string' || name.trim() === '') {
    return { message: 'Name is required', success: false }
  }

  if (typeof email !== 'string' || email.trim() === '') {
    return { message: 'Email is required', success: false }
  }

  if (typeof message !== 'string' || message.trim() === '') {
    return { message: 'Message is required', success: false }
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  if (!emailRegex.test(email)) {
    return { message: 'Please enter a valid email address', success: false }
  }

  console.log('Contact message received:', { name, email, message })

  return { message: 'Thank you for your message!', success: true }
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContactMessage, {
    message: '',
    success: false,
  })

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            required
          />
        </div>
        <div>
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            id="email"
            name="email"
            required
          />
        </div>
        <div>
          <label htmlFor="message">Message:</label>
          <textarea
            id="message"
            name="message"
            rows={5}
            required
          />
        </div>
        <button type="submit" disabled={isPending}>
          {isPending ? 'Sending...' : 'Send Message'}
        </button>
        {state.message && (
          <p style={{ color: state.success ? 'green' : 'red' }}>
            {state.message}
          </p>
        )}
      </form>
    </div>
  )
}
